      es: "Un santuario sagrado en Najicheván que, según la tradición local, es el lugar de sepultura de la figura bíblica de Noé.",
      pt: "Um santuário sagrado em Nakhchivan que, segundo a tradição local, é o local de sepultamento da figura bíblica de Noé.",
