      hu: ["Noé próféta feltételezett sírja.", "A 8. században épült.", "2006-ban jelentősen restaurálták.", "Szent zarándokhely.", "Helyi stílusú építészet jellemzi."],
      ro: ["Presupusul mormânt al profetului Noe.", "Construit în secolul al VIII-lea.", "Restaurat amplu în anul 2006.", "Un loc sfânt de pelerinaj.", "Arhitectură în stil local."],
